/* Main cards use conceptual diagrams; supplied evidence images are in galleries.js.
   Framing: every project is an AI / ML solution — the domain is the problem, the model is the work. */
window.PORTFOLIO_PROJECTS = [
 {id:'eacid', number:'01', title:'Teaching AI to\ndesign for the elements.', short:'EACID / AI inverse design framework', category:'PHYSICS-INFORMED AI', year:'ONGOING PHD RESEARCH', type:'wind', image:null, alt:'AI-generated wind turbine blade design and simulation', description:'EACID is a physics-informed cascade ML framework that generates complete designs from environmental requirements. Wind turbine blades are the testbed: site conditions, physical constraints, and icing are built into the model, and the design runs end to end with no human in the loop.', metric:'EACID', metricLabel:'ENVIRONMENTALLY ADAPTIVE CASCADE INVERSE DESIGN', tags:['Physics-informed ML','Cascade architecture','Generative design'], details:[['The question','Can an AI model generate a design for the environment it will actually operate in, icing conditions included, without a human in the loop?'],['The approach','EACID is a physics-informed cascade ML architecture. Blade element momentum (BEM) constraints act as a learning signal, icing-aware geometry generation handles hard operating conditions, and distributional conditioning learns from site data rather than a single design point.'],['The next step','The framework connects automated geometry generation with CFD evaluation, so the model’s designs are checked against physics under varying conditions. This is ongoing doctoral research; no completed performance benchmark is claimed.']], context:'AI PhD research · ELTE Doctoral School of Informatics · Supervisor: Prof. László Kollár'},
 {id:'antenna', number:'02', title:'From a target.\nTo a design, by AI.', short:'Cascade ML inverse design', category:'CASCADE ML / INVERSE DESIGN', year:'SELECTED PROJECT', type:'antenna', image:null, alt:'AI-generated patch antenna geometry and CST validation', description:'A four-stage ML cascade turns a goal (a material and a target frequency) into a complete physical design, with predicted performance. It is trained on an automated simulation dataset and deployed as a full web platform.', metric:'> 0.99', metricLabel:'R² · GENERATED GEOMETRY', tags:['Cascade ML','Ensemble learning','Data generation pipeline','Full-stack AI'], details:[['The challenge','Predicting one output is easy. Generating a full design whose parts stay consistent with each other, without leaking information between stages, is the real machine-learning problem.'],['The system','A Python–CST automation pipeline generated a synthetic dataset of 352 rectangular and 6,098 circular samples, with 24 physical feature descriptors and stratified sampling across six materials. Four cascaded models (voting ensembles of gradient boosting, random forests, and extra trees) predict geometry, then feed and impedance, then resonant frequency, then performance. Errors propagate realistically from stage to stage.'],['Reported results','R² > 0.99 for generated geometry; approximately 0.96 for resonant frequency, with approximately 5 MHz MAE; R² > 0.94 for gain and directivity. The circular extension achieved R² = 0.9896 for geometry and 0.9967 for directivity.'],['Reading the evaluations','The CV summary and the gallery contain different model evaluations. For example, the supplied M3 resonant-frequency plot reports R² = 0.6886 with 5.29 MHz MAE; it should not be confused with the geometry model’s R² score.'],['From model to product','A deployed web platform takes a material and a target frequency, generates the complete design, predicts its performance, visualises it, and cross-validates the AI’s output against CST simulation.']], context:'Independent AI project · Machine learning for inverse design'},
 {id:'beamforming', number:'03', title:'The right expert.\nFor every decision.', short:'TD3-MoE / Deep RL expert routing', category:'DEEP REINFORCEMENT LEARNING', year:'SELECTED PROJECT', type:'beam', image:null, alt:'Deep reinforcement learning mixture-of-experts routing dashboard', description:'A TD3 deep reinforcement learning agent with attention-supervised mixture-of-experts routing. It learns, state by state, which classical algorithm to trust and how to blend them, here applied to multi-user MIMO precoding.', metric:'33.434', metricLabel:'BITS/S/HZ · MEAN SUM RATE', tags:['Deep RL · TD3','Mixture of experts','Curriculum learning'], details:[['The question','Can a learned policy combine the strengths of several hand-designed algorithms, choosing and blending them as conditions change?'],['The approach','A TD3 actor-critic agent acts as the router of a mixture of experts. The supplied dashboard routes and blends ZF, MMSE, and MRT precoders according to channel state. Training spans 140,000 steps with curriculum learning (exploration noise annealed from 0.35 to 0.05). The broader framework in the CV also includes RZF and BD experts.'],['Supplied benchmark','The mean comparison chart reports TD3-MoE at 33.434 bits/s/Hz, versus 33.889 for pure ZF, 33.775 for pure MMSE, and 25.268 for uniform blending. That is approximately 1.34% below ZF, 1.01% below MMSE, and 32.3% above uniform blending.'],['Evaluation context','The CV separately reports 34.01 bits/s/Hz (99.76% of optimal), a Jain fairness index of 0.978, and 100% SNR-regime detection accuracy across a three-layer expert specialisation. Individual episode screenshots, training runs, and the aggregate benchmark are distinct summaries; the headline above uses the supplied aggregate comparison.']], context:'AI research project · Deep reinforcement learning & mixture of experts'},
 {id:'signal',number:'04',title:'Learning structure from data.',short:'GNN + TabTransformer prediction',category:'GRAPH NEURAL NETWORKS',year:'SELECTED PROJECT',type:'signal',image:null,alt:'Graph neural network prediction results',description:'A hybrid graph neural network and TabTransformer that predicts 5G signal strength and quality from 38,610 real-world measurements, beating spatial interpolation on held-out data.',metric:'0.906',metricLabel:'R² · HELD-OUT RSRP PREDICTION',tags:['GCN','TabTransformer','Graph learning'],details:[['The approach','A hybrid GCN and TabTransformer: the graph network learns spatial relationships across 386,100 KNN edges, and the transformer models tabular feature interactions. Two heads predict RSRP and a four-class signal-quality label. It was trained on 38,610 real-world 5G measurements from Cork.'],['Results','On 5,792 held-out measurements, with RSRP never used as an input: R² = 0.906, MAE 2.49 dB, RMSE 3.68 dB, and 81.1% signal-quality accuracy. That beats inverse-distance interpolation from the 10 nearest measurements (R² 0.882, MAE 3.05 dB, 64.5%).'],['Evaluation','A leakage-audited protocol with a fixed train/validation/test split, reproduced automatically in CI. A neighbours-only variant (R² 0.817) does not yet beat interpolation; purely spatial extrapolation is the next step.']],context:'Applied ML project · Graph learning on real-world data'},
 {id:'routing',number:'05',title:'Decisions that learn.',short:'Q-learning inside AODV routing',category:'REINFORCEMENT LEARNING',year:'SELECTED PROJECT',type:'signal',image:null,alt:'Q-learning AODV versus default AODV simulation results',description:'A Q-learning agent embedded in the AODV routing protocol: every node learns online whether to forward or drop route requests. In dense networks it halves delay and cuts route errors and routing overhead.',metric:'−50%',metricLabel:'END-TO-END DELAY · 500-NODE NETWORK',tags:['Q-learning','Online RL','ns-2 · C++'],details:[['The approach','Embedded a tabular Q-learning agent in AODV::recvRequest() in the ns-2 C++ source. At each route request, a node builds a state from hop count, link quality and congestion, chooses to forward or drop, and is rewarded by the outcome: +1 for replying as the destination, +0.8 from a cached route, +0.5 for forwarding, −1 for dropping. It learns online during the simulation.'],['Results','Compared with default AODV in 802.11 simulations of up to 500 mobile nodes. In the dense topologies (250 and 500 nodes, 30 minutes), it reduced end-to-end delay by 50–61%, routing overhead by 10–15% and route errors by 8–14%, at a throughput cost of at most 2.3%.'],['Evaluation','16 simulation runs across four topologies. Gains grow with network density and simulation time; in light 100-node networks the agent mainly reduces delay, with higher overhead.']],context:'AI research project · Reinforcement learning in network protocols'},
 {id:'odoo',number:'06',title:'Language meets operations.',short:'LLM assistant for Odoo ERP',category:'LLMS / AI AGENTS',year:'SELECTED PROJECT',type:'language',image:null,alt:'LLM-powered ERP assistant interface',description:'An LLM-powered assistant integrated into Odoo ERP.',metric:'LLM',metricLabel:'ERP ASSISTANT INTEGRATION',tags:['LLMs','Intent handling','Odoo ERP'],details:[['The project','Integrated an LLM chatbot assistant into Odoo ERP. The supplied screenshots show the installed ERP Chatbot Assistant module, a dedicated settings entry, and a chat interface with inventory and product shortcuts. The interface also includes chat sessions, chat logs, and intent configuration.']],context:'Applied AI project · Language models in production software'}
];
